    /**
     * Tests creating a new Seller.
     *
     * @return    Seller
     */
    public Seller testCreate() throws Throwable {
    Seller entity = null;

    LOGGER.info( "SellerTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a Seller");

    StringBuilder msg = new StringBuilder( "-- Failed to create a Seller" );

    try {
        entity = service.createSeller( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getSellerId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a Seller with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

    /**
     * Tests reading a Seller.
     *
     * @return    Seller
     */
    public Seller testRead() throws Throwable {
    LOGGER.info( "SellerTest:testRead()" );
    LOGGER.info( "-- Reading a previously created Seller" );

    Seller entity = null;
    StringBuilder msg = new StringBuilder( "-- Failed to read Seller with primary key" );
    msg.append( theId );

    try {
        entity = service.getSeller( new SellerFetchOneSummary(theId) );

        assertNotNull( entity,msg.toString() );

        // for use later
        theId = entity.getSellerId();

        LOGGER.info( "-- Successfully found Seller " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests updating a Seller.
     *
     * @return    Seller
     */
    public Seller testUpdate() throws Throwable {
    LOGGER.info( "SellerTest:testUpdate()" );
    LOGGER.info( "-- Attempting to update a Seller." );

    StringBuilder msg = new StringBuilder( "Failed to update a Seller : " );
    Seller entity = null;

    try {
        UpdateSellerCommand updateCommand = this.generateUpdateCommand();

        // apply the current id as to update the fields of the current entity
        updateCommand.setSellerId( theId );

        assertNotNull( updateCommand, msg.toString() );

        LOGGER.info( "-- Now updating the created Seller." );

        entity = service.updateSeller( updateCommand );

        assertNotNull( entity, msg.toString()  );

        LOGGER.info( "-- Successfully saved Seller - " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : primarykey-" + theId + " : entity-" +  entity + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests deleting a Seller.
     */
    public void testDelete() throws Throwable {
    LOGGER.info( "SellerTest:testDelete()" );
    LOGGER.info( "-- Deleting a previously created Seller." );

    try {
        DeleteSellerCommand deleteCommand = new DeleteSellerCommand( theId );

        service.delete( deleteCommand );

        LOGGER.info( "-- Successfully deleted Seller with primary key " + theId );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( "-- Failed to delete Seller with primary key " + theId );

        throw e;
    }
}

    /**
     * Tests getting all Sellers.
     *
     * @return    Collection
     */
    public List<Seller> testGetAll() throws Throwable {
    LOGGER.info( "SellerTest:testGetAll() - Retrieving Collection of Sellers:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Seller : " );
    List<Seller> collection  = null;

    try {
        // call the static get method on the SellerService
        collection = service.getAllSeller();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Seller currEntity  = null;
            Iterator<Seller> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getSellerId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

